<!DOCTYPE html>
<html>
<head>
  <title>Billiards</title>
  <style>
    body {
      margin: 0;
      overflow: hidden; /* Hide scrollbars */
      background-color: #333;
    }

    canvas {
      display: block;
    }

    #instructions {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      font-family: sans-serif;
      z-index: 100; /* Ensure instructions are on top */
      padding: 5px;
      background-color: rgba(0, 0, 0, 0.7);
    }

    #controls {
        position: absolute;
        top: 10px;
        right: 10px;
        color: white;
        font-family: sans-serif;
        z-index: 100;
        padding: 5px;
        background-color: rgba(0, 0, 0, 0.7);
    }

  </style>
</head>
<body>
  <canvas id="gameCanvas"></canvas>
  <div id="instructions">Drag the cue ball to aim and release to shoot!</div>
  <div id="controls">Reset / Rack</div>
  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const instructions = document.getElementById('instructions');
    const controlsDiv = document.getElementById('controls');

    window.sim = {
      W: 800,
      H: 600,
      R: 30,
      balls: [],
      cue: null,

      reset: function(balls) {
        this.balls = balls;
        this.cue = null;
      },

      step: function(dt) {
        for (let i = 0; i < this.balls.length; i++) {
          const ball = this.balls[i];
          if (!ball.potted) {
            ball.x += ball.vx * dt;
            ball.y += ball.vy * dt;

            // Bounce off walls
            if (ball.x + this.R > this.W || ball.x - this.R < 0) ball.vx = -ball.vx;
            if (ball.y + this.R > this.H || ball.y - this.R < 0) ball.vy = -ball.vy;

            // Ball-to-ball collisions
            for (let j = i + 1; j < this.balls.length; j++) {
              const otherBall = this.balls[j];
              if (!otherBall.potted) {
                const dx = ball.x - otherBall.x;
                const dy = ball.y - otherBall.y;
                const distSq = dx * dx + dy * dy;
                const minDistSq = this.R * this.R;

                if (distSq < minDistSq) {
                  // Collision detected
                  const mag = Math.sqrt(distSq);
                  const nx = dx / mag;
                  const ny = dy / mag;

                  ball.vx += nx * 0.5; // Rough approximation of energy loss
                  ball.vy += ny * 0.5;
                  otherBall.vx -= nx * 0.5;
                  otherBall.vy -= ny * 0.5;
                }
              }
            }

            // Pockets (simplified) - check if center is in pocket
            if (ball.x > this.W - this.R && ball.x < this.W + this.R && ball.y > this.H - this.R && ball.y < this.H + this.R) {
                ball.potted = true;
            }

          }
        }
      },

      state: function() {
        return this.balls.map(ball => ({
          x: ball.x,
          y: ball.y,
          vx: ball.vx,
          vy: ball.vy,
          potted: ball.potted,
          cue: ball.cue
        }));
      },

      shoot: function(vx, vy) {
        this.cue = { vx: vx, vy: vy };
      },

      pause: function() {
        window.requestAnimationFrame(null); // Stop animation loop
      },

      resume: function() {
        window.requestAnimationFrame(this.step.bind(this));
      }
    };

    let lastMouseX = 0;
    let lastMouseY = 0;

    canvas.addEventListener('mousedown', (e) => {
      const rect = canvas.getBoundingClientRect();
      lastMouseX = e.clientX - rect.left;
      lastMouseY = e.clientY - rect.top;

      // Check if mouse is over the cue ball (very basic)
      for (let i = 0; i < window.sim.balls.length; i++) {
        const ball = window.sim.balls[i];
        if (ball.cue) {
          window.sim.shoot(lastMouseX - window.sim.W / 2, lastMouseY - window.sim.H / 2); // Aim relative to canvas center
          break;
        }
      }

    });


    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      let mouseX = e.clientX - rect.left;
      let mouseY = e.clientY - rect.top;

        // Reset mouse coordinates if not down
        if (!window.sim.cue){
            lastMouseX = mouseX;
            lastMouseY = mouseY;
            return;
        }
    });


    canvas.addEventListener('mouseup', () => {
      window.sim.cue = null; // Reset cue after release
    });

    // Initial setup: create balls, reset layout
    const initialBalls = [
      { x: 200, y: 200, vx: 1, vy: 2, cue: true },  // Cue ball
      { x: 500, y: 200, vx: -1, vy: 1, cue: false}, // Ball 1
      { x: 300, y: 500, vx: 0.5, vy: -1, cue: false},// Ball 2
      { x: 700, y: 500, vx: -0.5, vy: -1, cue: false}  //Ball 3
    ];

    window.sim.reset(initialBalls);
    window.sim.resume();


    controlsDiv.addEventListener('click', () => {
        window.sim.reset(initialBalls);
        window.sim.resume();
    });

  </script>
</body>
</html>
